(O/'pikachuForwardTiltHurtboxes.ts').write_text('''/** Actual body/overlay-reviewed target capsules for original neutral ftilt.\n * Source2Dprojection/radius calibration; no native3Dcollision or patch parity claim. */\nimport type { AttackMoveWithAnimation, MoveHurtboxModifier } from './moveSchema';\nimport { buildPikachuNormalMove } from './pikachuNormalMoves';\nimport { pikachuForwardTiltPoseProjector } from './pikachuForwardTiltPose';\nexport const PIKACHU_FORWARD_TILT_AUTHORED_HURTBOX_POSES = '''+json.dumps(ft,separators=(',',':'))+''' as const;\nexport function buildPikachuForwardTiltWithAuthoredHurtboxes(): AttackMoveWithAnimation {\n  const poses = PIKACHU_FORWARD_TILT_AUTHORED_HURTBOX_POSES;\n  const hurtboxModifiers: MoveHurtboxModifier[] = poses.flatMap(row=>row.hurtboxes.map(hurtbox=>({\n    frameWindow:{startFrame:row.startElapsed,endFrame:row.endElapsed},replaceBody:true,hurtbox})));\n  return {...buildPikachuNormalMove('forward-tilt',pikachuForwardTiltPoseProjector),hurtboxModifiers,\n    animation:{startupFrames:2,activeFrames:3,recoveryFrames:3,frameWindows:poses.map((row,artFrameIndex)=>({\n      startFrame:row.startElapsed,endFrame:row.endElapsed,artFrameIndex}))}};\n}\n''')
(O/'pikachuChargeHurtboxes.ts').write_text('''/** Actual15charge-body/overlay reviewed target capsules, held motion clock0..60.\n * The full-power final pose holds beyond60; native keep/expiry status remains separate. */\nconst POSES = '''+json.dumps(charges,separators=(',',':'))+''' as const;\nexport type PikachuSmashChargeAction = 'forward-smash'|'up-smash'|'down-smash'|'forward-smash-charge'|'up-smash-charge'|'down-smash-charge';\nexport function selectPikachuSmashChargeHurtboxes(action:PikachuSmashChargeAction,heldFrames:number) {\n  if(!Number.isInteger(heldFrames)||heldFrames<0) return null;\n  const chargeAction = action.endsWith('-charge') ? action : `${action}-charge`;\n  const frame = Math.min(60,heldFrames);\n  return POSES.find(row=>row.action===chargeAction && frame>=row.startElapsed && frame<row.endElapsed)?.hurtboxes ?? null;\n}\n''')
